34	const BASE_PREMIUMS: Record<string, number> = {
35	  sword: 100,
36	  amulet: 60,
37	  staff: 80,
38	  potion: 40,
39	  rune: 25,
40	  moonstone: 25,
41	};
42	
43	// Percentages are applied as integer arithmetic (× percent ÷ 100) rather than
44	// as a float rate (× 1.1): this keeps intermediate values integral and avoids
45	// binary floating-point error — 100 * 1.1 is 110.00000000000001, but
46	// (100 * 110) / 100 is exact. Premiums round up in MHPCO's favour at the end.
47	const ONE_HUNDRED_PERCENT = 100;
48	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
49	const ADMIN_FEE = 5;
50	
51	const applyPercent = (amount: number, percent: number): number =>
52	  (amount * percent) / ONE_HUNDRED_PERCENT;
53	
54	const addSurcharge = (amount: number, surchargePercent: number): number =>
55	  applyPercent(amount, ONE_HUNDRED_PERCENT + surchargePercent);
56	
57	const COMPONENT_TYPES = ["rune", "moonstone"];
58	const BUILDING_BLOCK_SIZE = 3;
59	const BUILDING_BLOCK_BASE_PREMIUM = 60;
60	
61	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
62	
63	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
64	
65	const sumBasePremiums = (items: Item[]): number =>
66	  items.reduce((total, item) => total + basePremiumOf(item), 0);
67	
68	// Alike components are grouped into building blocks of 3, which carry a
69	// special base premium; the remaining components are priced individually.
70	// Total over the empty group: no components means no blocks and no remainder.
71	const alikeComponentsBasePremium = (components: Item[]): number => {
72	  const blockCount = Math.floor(components.length / BUILDING_BLOCK_SIZE);
73	  const unblocked = components.slice(blockCount * BUILDING_BLOCK_SIZE);
74	  return blockCount * BUILDING_BLOCK_BASE_PREMIUM + sumBasePremiums(unblocked);
75	};
76	
77	const groupByType = (items: Item[]): Item[][] => [
78	  ...items
79	    .reduce(
80	      (groups, item) =>
81	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
82	      new Map<string, Item[]>(),
83	    )
84	    .values(),
85	];
86	
87	// Splits items into those matching the predicate and those that do not, in a
88	// single pass — the two groups are priced by different rules.
89	const partition = <T>(
90	  items: T[],
91	  matches: (item: T) => boolean,
92	): { matching: T[]; rest: T[] } => {
93	  const matching: T[] = [];
94	  const rest: T[] = [];
95	  for (const item of items) {
96	    if (matches(item)) {
97	      matching.push(item);
98	    } else {
99	      rest.push(item);
100	    }
101	  }
102	  return { matching, rest };
103	};
104	
105	const totalBasePremium = (items: Item[]): number => {
106	  const { matching: components, rest: mainItems } = partition(items, isComponent);
107	  const componentsTotal = groupByType(components).reduce(
108	    (total, alike) => total + alikeComponentsBasePremium(alike),
109	    0,
110	  );
111	  return sumBasePremiums(mainItems) + componentsTotal;
112	};
113	
114	const quote = (step: QuoteStep): QuoteResult => {
115	  const basePremium = totalBasePremium(step.items);
116	  const premiumAfterFirstInsurance = addSurcharge(
117	    basePremium,
118	    FIRST_INSURANCE_SURCHARGE_PERCENT,
119	  );
120	  return { premium: Math.ceil(premiumAfterFirstInsurance) + ADMIN_FEE };
121	};
122	
123	export const runScenario = (scenario: Scenario): ScenarioResult => ({
124	  results: scenario.steps.map(quote),
125	});
