// Components and main items are priced by different rules, so each group is
// totalled separately: components by building block, main items item by item.
const componentsBasePremium = (components: Item[]): number =>
  groupByType(components).reduce(
    (total, alike) => total + alikeComponentsBasePremium(alike),
    0,
  );

const totalBasePremium = (items: Item[]): number =>
  sumBasePremiums(items.filter((item) => !isComponent(item))) +
  componentsBasePremium(items.filter(isComponent));
